import json,pathlib,subprocess,hashlib,datetime,concurrent.futures,urllib.parse
R=pathlib.Path(__file__).resolve().parents[1]
targets=[(90, 'Mogensen2006', 'https://doi.org/10.1016/j.fgb.2006.03.003'), (90, 'Shcolnick2006', 'https://doi.org/10.1016/j.bbabio.2006.11.015'), (116, 'Durner2001', 'https://doi.org/10.1002/1097-0290(20010205)72:3<278::AID-BIT4>3.0.CO;2-G'), (116, 'SchaechterPDF', 'https://www.microbiologyresearch.org/deliver/fulltext/micro/19/3/mic-19-3-592.pdf?itemId=/content/journal/micro/10.1099/00221287-19-3-592&mimeType=pdf'), (116, 'HassanEPMCpdf', 'https://europepmc.org/articles/PMC235284?pdf=render'), (116, 'TsengEPMCpdf', 'https://europepmc.org/articles/PMC197015?pdf=render'), (116, 'HassanPMCpdf', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC235284/pdf/jbacter00609-0271.pdf'), (116, 'TsengPMCpdf', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC197015/pdf/jbacter00034-0195.pdf'), (116, 'HassanASMPDF', 'https://journals.asm.org/doi/pdf/10.1128/jb.130.2.805-811.1977'), (116, 'TsengASMPDF', 'https://journals.asm.org/doi/pdf/10.1128/jb.176.21.6599-6605.1994'), (90, 'Zhu2005PDF', 'https://www.sciencedirect.com/science/article/pii/S1096717604000989/pdfft'), (91, 'SigmaV6629', 'https://www.sigmaaldrich.com/US/en/product/sigma/v6629'), (91, 'UTEXDAS', 'https://utex.org/products/das-vitamin-cocktail'), (111, 'NBRC1620', 'https://www.nite.go.jp/nbrc/catalogue/NBRCMediumDetailServlet?NO=1620')]
def fetch(t):
 i,fam,url=t;p=R/'captures'/('b-remediation-'+hashlib.sha256(url.encode()).hexdigest()[:16]+'.body');at=datetime.datetime.now(datetime.timezone.utc).isoformat();q=subprocess.run(['curl','-L','-sS','--connect-timeout','5','--max-time','18','-o',str(p),'-w','%{http_code}\n%{url_effective}\n%{content_type}',url],capture_output=True);s=q.stdout.decode(errors='replace').splitlines();e={'case_index':i,'family':fam,'url':url,'accessed_at':at,'transport_success':q.returncode==0,'http_status':s[0] if s else None,'final_url':s[1] if len(s)>1 else None,'content_type':s[2] if len(s)>2 else None,'error':q.stderr.decode(errors='replace')}
 if p.exists():
  ext='.pdf' if p.read_bytes().startswith(b'%PDF') else '.json' if 'json' in str(e['content_type']) else '.xml' if 'xml' in str(e['content_type']) else '.html';dest=p.with_suffix(ext);p.rename(dest);e.update(path=dest.relative_to(R).as_posix(),sha256=hashlib.sha256(dest.read_bytes()).hexdigest(),bytes=dest.stat().st_size)
 return e
with concurrent.futures.ThreadPoolExecutor(max_workers=6) as ex:out=list(ex.map(fetch,targets))
(R/'parts/b-remediation2-retrievals.json').write_text(json.dumps(out,indent=2))
print([(x['case_index'],x['family'],x['http_status'],x.get('bytes')) for x in out])
